import path from 'path';
import { readFileSync } from 'fs';
import { test, expect, Page } from '@playwright/test';
import { cleanUpStoredFiles, uniqueFileName } from '../helpers';

// Visio is view-only and has no blank create-new template, so these tests upload a fixture
// (generated by fixtures/make-vsdx.py) and open it.
const FIXTURE = path.join(__dirname, '..', '..', 'fixtures', 'minimal.vsdx');
const EDITOR_IFRAME = 'iframe[name="frameEditor"]';

const storedFiles: string[] = [];

async function uploadFixture(page: Page): Promise<string> {
  const res = await page.request.post('/example/upload', {
    multipart: {
      uploadedFile: {
        name: uniqueFileName('visio', 'vsdx'),
        mimeType: 'application/vnd.ms-visio.drawing',
        buffer: readFileSync(FIXTURE),
      },
    },
  });
  expect(res.ok()).toBe(true);
  const body = (await res.json()) as { filename?: string; error?: string };
  expect(body.error).toBeUndefined();
  storedFiles.push(body.filename as string);
  return body.filename as string;
}

// Collects uncaught errors from the page and its iframes, registered before goto() so a
// failure during SDK start-up (web-apps#357) is not missed.
function collectPageErrors(page: Page): string[] {
  const errors: string[] = [];
  page.on('pageerror', (err) => errors.push(err.message));
  return errors;
}

test.describe('Visio - open existing file', { tag: ['@visio', '@smoke', '@regression'] }, () => {
  test.afterAll(async ({ browser }) => {
    await cleanUpStoredFiles(browser, storedFiles);
  });

  test('desktop editor opens a vsdx', async ({ page }) => {
    const errors = collectPageErrors(page);
    const fileName = await uploadFixture(page);

    await page.goto(`/example/editor?fileName=${encodeURIComponent(fileName)}`);

    const editorIframe = page.locator(EDITOR_IFRAME);
    await expect(editorIframe).toHaveAttribute('src', /visioeditor\/main/);

    const frame = page.frameLocator(EDITOR_IFRAME);
    await expect(frame.locator('#loading-mask')).toBeHidden({ timeout: 30_000 });
    // A file that fails to open (x2t error, broken SDK) still hides the mask, so check for the alert too
    await expect(frame.locator('.asc-window.alert')).toHaveCount(0);
    await expect(frame.locator('#editor_sdk canvas').first()).toBeVisible();
    expect(errors).toEqual([]);
  });

  test('mobile editor opens a vsdx', { tag: '@mobile' }, async ({ page }) => {
    await page.setViewportSize({ width: 414, height: 896 });
    const errors = collectPageErrors(page);
    const fileName = await uploadFixture(page);

    // ?type=mobile forces the mobile bundle (bypasses UA sniffing in nodejs/app.js)
    await page.goto(`/example/editor?fileName=${encodeURIComponent(fileName)}&type=mobile`);

    const editorIframe = page.locator(EDITOR_IFRAME);
    await expect(editorIframe).toHaveAttribute('src', /visioeditor\/mobile/);

    // Same load signal as mobile-editor.spec.ts: the skeleton shows, then clears
    const frame = page.frameLocator(EDITOR_IFRAME);
    const placeholder = frame.locator('.doc-placeholder');
    await expect(placeholder.first()).toBeVisible();
    await expect(placeholder).toHaveCount(0, { timeout: 30_000 });
    await expect(frame.locator('.dialog.modal-in, .notification.modal-in')).toHaveCount(0);
    await expect(frame.locator('#editor_sdk canvas').first()).toBeVisible();
    expect(errors).toEqual([]);
  });
});
